<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard</title><link rel="stylesheet" href="assets/admin.css"></head><body><aside class="sidebar"><div class="logo">DW</div><nav><a class="active" href="index.php">Dashboard</a><a href="templates.php">Template</a><a href="new.php">Buat Undangan</a><a href="logout.php">Keluar</a></nav></aside><main class="app"><header><div><h1>Dashboard Undangan</h1><p>Pilih template, isi data klien, publish. Template asli tidak berubah.</p></div><a class="btn primary" href="new.php">+ Pesanan Baru</a></header><section class="stats"><div><b><?=count($items)?></b><span>Total Undangan</span></div><div><b><?=count($ts)?></b><span>Template</span></div><div><b><?=array_sum(array_map(fn($x)=>(int)($x['guest_count']??0),$items))?></b><span>Total Tamu</span></div></section><section class="panel"><div class="panel-head"><h2>Pesanan Terbaru</h2></div><?php if(!$items):?><div class="empty">Belum ada pesanan. Klik <b>Pesanan Baru</b> untuk mulai.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Judul</th><th>Template</th><th>Slug</th><th>Tamu</th><th>Status</th><th>Update</th><th></th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><b><?=e($it['title']??$it['slug'])?></b></td><td><?=e($ts[$it['template']]['name']??$it['template'])?></td><td>/<?=e($it['slug'])?></td><td><a class="guest-count" href="guests.php?slug=<?=urlencode($it['slug'])?>"><?= (int)($it['guest_count']??0) ?> tamu</a></td><td><span class="badge <?=e($it['status']??'draft')?>"><?=e($it['status']??'draft')?></span></td><td><?=e(date('d M Y H:i',strtotime($it['updated_at']??'now')))?></td><td class="actions"><a href="guests.php?slug=<?=urlencode($it['slug'])?>">Tamu</a><a href="editor.php?slug=<?=urlencode($it['slug'])?>">Edit</a><a target="_blank" href="view.php?slug=<?=urlencode($it['slug'])?>">Lihat</a></td></tr><?php endforeach?></tbody></table></div><?php endif?></section></main></body></html>
